from dataclasses import dataclass

@dataclass(frozen=True)
class RequestBudget:
    max_downstream_calls: int = 3
    deadline_ms: int = 250
    max_bytes_scanned: int = 256 * 1024
    max_page: int = 100

class Policy:  # seam: volatile rules live here, not in hot path
    name: str
    version: int
    def decide(self, ctx: dict) -> dict:
        raise NotImplementedError

class Registry:
    def __init__(self):
        self._policies: dict[tuple[str, int], Policy] = {}
    def register(self, p: Policy):
        self._policies[(p.name, p.version)] = p
    def get(self, name: str, version: int) -> Policy:
        return self._policies[(name, version)]

def handle(req: dict, budget: RequestBudget, registry: Registry):
    if len(req.get("items", [])) > budget.max_page:
        return {"status": 400, "error": "page too large"}  # shed before cost
    policy = registry.get(req["policy"], req["v"])
    # caller enforces deadline_ms and counts bytes_scanned against budget
    return {"status": 200, "decision": policy.decide(req)}
